<?php
declare(strict_types=1);
require __DIR__.'/fixtures/image-handoff-v3/ImageHandoffV3.php';
if(!extension_loaded('pdo_sqlite'))throw new RuntimeException('Real PDO SQLite required; never skip');
$n=0;
function ok(bool $v,string $m):void{global $n;if(!$v)throw new RuntimeException($m);$n++;}
function fail(callable $f):Throwable{try{$f();}catch(Throwable $e){return $e;}throw new RuntimeException('Expected failure');}
function db(array $values):PDO{$d=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$d->exec(file_get_contents(__DIR__.'/../database/schema.sqlite.sql'));foreach($values as $id=>$url){$q=$d->prepare('INSERT INTO products(id,name,price,image_url) VALUES(?,?,1,?)');$q->execute([$id,'synthetic',$url]);}ImageHandoffV3::migrate($d,count($values));return $d;}
$d=db([1=>str_repeat('x',2049),2=>'/good.jpg']);$r=ImageHandoffV3::consume($d,3);ok($r===['handed_off'=>1,'quarantined'=>1,'skipped'=>1,'changed'=>0,'scanned'=>3],'poison isolated then valid progresses');ok($d->query('SELECT acknowledged_revision FROM image_product_dirty ORDER BY product_id')->fetchAll(PDO::FETCH_COLUMN)===[0,1],'poison not ACKed');ok($d->query('SELECT product_id,revision,reason FROM image_handoff_quarantine')->fetchAll(PDO::FETCH_NUM)===[[1,1,'field_bounds']],'exact revision bounded diagnostic');
$d->exec("UPDATE products SET image_url='/repaired.jpg' WHERE id=1");$r=ImageHandoffV3::consume($d,2);ok($r['handed_off']===1,'new revision bypasses old quarantine');ok($d->query('SELECT revision,acknowledged_revision FROM image_product_dirty WHERE product_id=1')->fetchAll(PDO::FETCH_NUM)===[[2,2]],'new revision ACK only');ok((int)$d->query('SELECT count(*) FROM image_handoff_quarantine')->fetchColumn()===1,'old diagnostic retained');
$d=db([1=>"\xFF",2=>'/good.jpg']);$r=ImageHandoffV3::consume($d,3);ok($r['handed_off']===1 && $r['quarantined']===1,'UTF8 poison isolated');ok($d->query('SELECT reason FROM image_handoff_quarantine')->fetchColumn()==='invalid_utf8','typed UTF8 reason');
$d=db([1=>'/a.jpg',2=>str_repeat('x',2049),3=>'/c.jpg']);$r=ImageHandoffV3::consume($d,4);ok($r['handed_off']===2 && $r['quarantined']===1,'middle poison and successes');ok($r['scanned']===4,'scan bound includes poison skips');
$d=db([1=>'/a.jpg',2=>'/b.jpg']);ImageHandoffV3::consume($d,1);$d->exec("UPDATE products SET image_url='/new-a.jpg' WHERE id=1");for($id=3;$id<8;$id++){$d->exec("INSERT INTO products(id,name,price,image_url) VALUES($id,'synthetic',1,'/new.jpg')");ImageHandoffV3::consume($d,1);}ok((int)$d->query('SELECT acknowledged_revision FROM image_product_dirty WHERE product_id=1')->fetchColumn()===2,'fixed epoch revisits low ID despite continuous inserts');
$d=db([1=>'/a.jpg']);$d->exec("INSERT INTO image_snapshot_handoff VALUES(1,1,'bad','".str_repeat('0',64)."')");$e=fail(fn()=>ImageHandoffV3::consume($d,1));ok($e->getMessage()==='Conflicting handoff','integrity error surfaces');ok((int)$d->query('SELECT count(*) FROM image_handoff_quarantine')->fetchColumn()===0,'integrity never quarantined');ok((int)$d->query('SELECT acknowledged_revision FROM image_product_dirty')->fetchColumn()===0,'conflict no ACK');
$d=db([1=>str_repeat('x',2049)]);$d->exec("INSERT INTO image_snapshot_handoff VALUES(1,1,'bad','".str_repeat('0',64)."')");$e=fail(fn()=>ImageHandoffV3::consume($d,1));ok($e->getMessage()==='Invalid content has persisted handoff','poison with persisted handoff fails closed');ok((int)$d->query('SELECT count(*) FROM image_handoff_quarantine')->fetchColumn()===0,'no corruption quarantine');
$d=db([1=>str_repeat('x',2049)]);$r=ImageHandoffV3::consume($d,1);ok($r['scanned']===1 && $r['quarantined']===1,'bounded poison call');$r=ImageHandoffV3::consume($d,5);ok($r['scanned']===5 && $r['skipped']===5 && $r['handed_off']===0,'all-held termination bounded');
$d=db([1=>str_repeat('x',2049)]);$d->exec('UPDATE image_product_dirty SET deleted=1');$e=fail(fn()=>ImageHandoffV3::consume($d,1));ok($e->getMessage()==='Live row contradicts tombstone','contradiction precedes content bounds');ok((int)$d->query('SELECT count(*) FROM image_handoff_quarantine')->fetchColumn()===0,'contradiction never quarantined');
echo "PASS $n v3 poison isolation checks\n";
